-- ============================================================================
-- DOMAIN A: SOURCE (Procurement & Inbound)
-- ============================================================================

CREATE TABLE suppliers (
    id INTEGER PRIMARY KEY,
    supplier_code VARCHAR UNIQUE NOT NULL,
    name VARCHAR NOT NULL,
    city VARCHAR,
    country VARCHAR NOT NULL,
    lat DECIMAL(10,6),
    lon DECIMAL(10,6),
    tier INTEGER NOT NULL DEFAULT 1,
    is_active BOOLEAN DEFAULT true
);

CREATE TABLE ingredients (
    id INTEGER PRIMARY KEY,
    ingredient_code VARCHAR UNIQUE NOT NULL,
    name VARCHAR NOT NULL,
    category VARCHAR NOT NULL,
    subcategory VARCHAR,
    bom_level INTEGER DEFAULT 2,
    weight_kg DECIMAL(12,4),
    cost_per_kg DECIMAL(12,4),
    unit_of_measure VARCHAR NOT NULL DEFAULT 'kg',
    is_active BOOLEAN DEFAULT true
);

CREATE TABLE supplier_ingredients (
    id INTEGER PRIMARY KEY,
    supplier_id INTEGER NOT NULL,
    ingredient_id INTEGER NOT NULL,
    unit_cost DECIMAL(12,4) NOT NULL,
    lead_time_days INTEGER NOT NULL,
    min_order_qty DECIMAL(12,2) NOT NULL,
    FOREIGN KEY (supplier_id) REFERENCES suppliers(id),
    FOREIGN KEY (ingredient_id) REFERENCES ingredients(id)
);

CREATE TABLE purchase_orders (
    id INTEGER PRIMARY KEY,
    po_number VARCHAR NOT NULL,
    supplier_id INTEGER,
    plant_id INTEGER,
    order_date INTEGER NOT NULL,
    status VARCHAR DEFAULT 'open',
    transaction_sequence_id BIGINT NOT NULL,
    FOREIGN KEY (supplier_id) REFERENCES suppliers(id)
);

CREATE TABLE purchase_order_lines (
    po_id INTEGER NOT NULL,
    line_number INTEGER NOT NULL,
    ingredient_id INTEGER NOT NULL,
    quantity_kg DECIMAL(12,2) NOT NULL,
    unit_cost DECIMAL(10,4),
    status VARCHAR DEFAULT 'open',
    FOREIGN KEY (po_id) REFERENCES purchase_orders(id),
    PRIMARY KEY (po_id, line_number)
);

CREATE TABLE goods_receipts (
    id INTEGER PRIMARY KEY,
    gr_number VARCHAR UNIQUE NOT NULL,
    shipment_id INTEGER,
    plant_id INTEGER,
    receipt_date INTEGER NOT NULL,
    status VARCHAR DEFAULT 'received',
    transaction_sequence_id BIGINT NOT NULL
);

CREATE TABLE goods_receipt_lines (
    gr_id INTEGER NOT NULL,
    line_number INTEGER NOT NULL,
    ingredient_id INTEGER NOT NULL,
    quantity_kg DECIMAL(12,2) NOT NULL,
    FOREIGN KEY (gr_id) REFERENCES goods_receipts(id),
    PRIMARY KEY (gr_id, line_number)
);

-- ============================================================================
-- DOMAIN B: TRANSFORM (Manufacturing)
-- ============================================================================

CREATE TABLE plants (
    id INTEGER PRIMARY KEY,
    plant_code VARCHAR UNIQUE NOT NULL,
    name VARCHAR NOT NULL,
    city VARCHAR NOT NULL,
    country VARCHAR NOT NULL,
    lat DECIMAL(10,6),
    lon DECIMAL(10,6),
    capacity_tons_per_day DECIMAL(10,2),
    is_active BOOLEAN DEFAULT true
);

CREATE TABLE production_lines (
    id INTEGER PRIMARY KEY,
    line_code VARCHAR UNIQUE NOT NULL,
    name VARCHAR NOT NULL,
    plant_id INTEGER NOT NULL,
    line_type VARCHAR NOT NULL,
    capacity_units_per_hour INTEGER NOT NULL,
    is_active BOOLEAN DEFAULT true,
    FOREIGN KEY (plant_id) REFERENCES plants(id)
);

CREATE TABLE formulas (
    id INTEGER PRIMARY KEY,
    formula_code VARCHAR UNIQUE NOT NULL,
    name VARCHAR NOT NULL,
    product_id INTEGER,
    bom_level INTEGER NOT NULL DEFAULT 0,
    batch_size_kg DECIMAL(10,2) NOT NULL,
    yield_percent DECIMAL(5,2) DEFAULT 98.0,
    run_rate_cases_per_hour DECIMAL(10,2),
    changeover_time_hours DECIMAL(5,2)
);

CREATE TABLE formula_ingredients (
    formula_id INTEGER NOT NULL,
    ingredient_id INTEGER NOT NULL,
    sequence INTEGER NOT NULL,
    quantity_kg DECIMAL(10,6) NOT NULL,
    FOREIGN KEY (formula_id) REFERENCES formulas(id),
    PRIMARY KEY (formula_id, ingredient_id, sequence)
);

CREATE TABLE work_orders (
    id INTEGER PRIMARY KEY,
    wo_number VARCHAR UNIQUE NOT NULL,
    plant_id INTEGER NOT NULL,
    formula_id INTEGER NOT NULL,
    planned_quantity_kg DECIMAL(12,2) NOT NULL,
    planned_start_date INTEGER NOT NULL,
    due_date INTEGER,
    status VARCHAR DEFAULT 'planned',
    transaction_sequence_id BIGINT NOT NULL
);

CREATE TABLE batches (
    id INTEGER PRIMARY KEY,
    batch_number VARCHAR UNIQUE NOT NULL,
    wo_id INTEGER,
    plant_id INTEGER,
    formula_id INTEGER,
    product_id INTEGER,
    quantity_kg DECIMAL(12,2) NOT NULL,
    yield_percent DECIMAL(5,2),
    production_date INTEGER NOT NULL,
    status VARCHAR DEFAULT 'pending',
    product_type VARCHAR,
    bom_level INTEGER DEFAULT 0,
    transaction_sequence_id BIGINT NOT NULL,
    FOREIGN KEY (plant_id) REFERENCES plants(id),
    FOREIGN KEY (formula_id) REFERENCES formulas(id)
);

CREATE TABLE batch_ingredients (
    id INTEGER PRIMARY KEY,
    batch_id INTEGER NOT NULL,
    ingredient_id INTEGER NOT NULL,
    quantity_kg DECIMAL(12,4) NOT NULL,
    FOREIGN KEY (batch_id) REFERENCES batches(id)
);

