CREATE TABLE bulk_intermediates (
    id INTEGER PRIMARY KEY,
    bulk_code VARCHAR UNIQUE NOT NULL,
    name VARCHAR NOT NULL,
    category VARCHAR,
    bom_level INTEGER NOT NULL DEFAULT 1,
    weight_kg DECIMAL(12,4),
    cost_per_kg DECIMAL(12,4),
    unit_of_measure VARCHAR DEFAULT 'kg',
    is_active BOOLEAN DEFAULT true
);

CREATE TABLE skus (
    id INTEGER PRIMARY KEY,
    sku_code VARCHAR UNIQUE NOT NULL,
    name VARCHAR NOT NULL,
    category VARCHAR,
    brand VARCHAR,
    units_per_case INTEGER DEFAULT 12,
    weight_kg DECIMAL(10,2),
    cost_per_case DECIMAL(10,2),
    price_per_case DECIMAL(10,2),
    value_segment VARCHAR,
    is_active BOOLEAN DEFAULT true,
    supersedes_sku_id INTEGER
);

-- ============================================================================
