    is_active BOOLEAN DEFAULT true
);

CREATE TABLE gl_journal (
    id INTEGER PRIMARY KEY,
    transaction_sequence_id BIGINT NOT NULL,
    entry_date INTEGER NOT NULL,
    posting_date INTEGER NOT NULL,
    account_code VARCHAR NOT NULL,
    debit_amount DECIMAL(14,4) DEFAULT 0,
    credit_amount DECIMAL(14,4) DEFAULT 0,
    reference_type VARCHAR NOT NULL,
    reference_id VARCHAR,
    node_id VARCHAR,
    product_id VARCHAR,
    description VARCHAR,
    is_reversal BOOLEAN DEFAULT false
);

CREATE TABLE ap_invoices (
    id INTEGER PRIMARY KEY,
    transaction_sequence_id BIGINT NOT NULL,
    invoice_number VARCHAR UNIQUE NOT NULL,
    supplier_id INTEGER,
    gr_id INTEGER,
    invoice_date INTEGER NOT NULL,
    due_date INTEGER NOT NULL,
    total_amount DECIMAL(14,4) NOT NULL,
    currency VARCHAR DEFAULT 'USD',
    status VARCHAR DEFAULT 'open',
    FOREIGN KEY (supplier_id) REFERENCES suppliers(id),
    FOREIGN KEY (gr_id) REFERENCES goods_receipts(id)
);

CREATE TABLE ap_invoice_lines (
    invoice_id INTEGER NOT NULL,
    line_number INTEGER NOT NULL,
    ingredient_id INTEGER NOT NULL,
    quantity_kg DECIMAL(12,4) NOT NULL,
    unit_cost DECIMAL(10,4) NOT NULL,
    line_amount DECIMAL(14,4) NOT NULL,
    FOREIGN KEY (invoice_id) REFERENCES ap_invoices(id),
    PRIMARY KEY (invoice_id, line_number)
);

CREATE TABLE ar_invoices (
    id INTEGER PRIMARY KEY,
    transaction_sequence_id BIGINT NOT NULL,
    invoice_number VARCHAR UNIQUE NOT NULL,
    customer_location_id INTEGER,
    shipment_id INTEGER,
    invoice_date INTEGER NOT NULL,
    due_date INTEGER NOT NULL,
    total_amount DECIMAL(14,4) NOT NULL,
    currency VARCHAR DEFAULT 'USD',
    channel VARCHAR,
    status VARCHAR DEFAULT 'open',
    FOREIGN KEY (shipment_id) REFERENCES shipments(id)
);

CREATE TABLE ar_invoice_lines (
    invoice_id INTEGER NOT NULL,
    line_number INTEGER NOT NULL,
    sku_id INTEGER NOT NULL,
    quantity_cases DECIMAL(12,2) NOT NULL,
    unit_price DECIMAL(10,4) NOT NULL,
    line_amount DECIMAL(14,4) NOT NULL,
    FOREIGN KEY (invoice_id) REFERENCES ar_invoices(id),
    PRIMARY KEY (invoice_id, line_number)
);

-- ============================================================================
-- DOMAIN: TRADE MANAGEMENT
-- ============================================================================

CREATE TABLE trade_programs (
    id INTEGER PRIMARY KEY,
    program_code VARCHAR UNIQUE NOT NULL,
    name VARCHAR NOT NULL,
    channel_id INTEGER NOT NULL,
    program_type VARCHAR NOT NULL,
    rate_pct DECIMAL(8,4) NOT NULL,
    start_day INTEGER NOT NULL,
    end_day INTEGER NOT NULL,
    is_active BOOLEAN DEFAULT true,
    FOREIGN KEY (channel_id) REFERENCES channels(id)
);

CREATE TABLE promo_events (
    id INTEGER PRIMARY KEY,
    event_code VARCHAR UNIQUE NOT NULL,
    name VARCHAR NOT NULL,
    trade_program_id INTEGER NOT NULL,
    promo_type VARCHAR NOT NULL,
    sku_id INTEGER NOT NULL,
    start_day INTEGER NOT NULL,
    end_day INTEGER NOT NULL,
    lift_pct DECIMAL(8,4),
    incremental_spend DECIMAL(14,4),
    status VARCHAR DEFAULT 'planned',
    FOREIGN KEY (trade_program_id) REFERENCES trade_programs(id),
    FOREIGN KEY (sku_id) REFERENCES skus(id)
);

CREATE TABLE trade_deductions (
    id INTEGER PRIMARY KEY,
    trade_program_id INTEGER NOT NULL,
    promo_event_id INTEGER,
    ar_invoice_id INTEGER NOT NULL,
    ar_line_number INTEGER NOT NULL,
    sku_id INTEGER NOT NULL,
    list_price_per_case DECIMAL(10,4) NOT NULL,
    quantity_cases DECIMAL(12,2) NOT NULL,
    deduction_amount DECIMAL(14,4) NOT NULL,
    FOREIGN KEY (trade_program_id) REFERENCES trade_programs(id),
    FOREIGN KEY (promo_event_id) REFERENCES promo_events(id),
    FOREIGN KEY (ar_invoice_id) REFERENCES ar_invoices(id),
    FOREIGN KEY (sku_id) REFERENCES skus(id)
);

-- ============================================================================
-- DOMAIN H2: DATA QUALITY & VARIANCES
-- ============================================================================

CREATE TABLE invoice_variances (
    id INTEGER PRIMARY KEY,
    invoice_id INTEGER NOT NULL,
    line_number INTEGER NOT NULL,
    variance_type VARCHAR NOT NULL,
    expected_value DECIMAL(14,4) NOT NULL,
    actual_value DECIMAL(14,4) NOT NULL,
    variance_amount DECIMAL(14,4) NOT NULL,
    resolution_status VARCHAR DEFAULT 'open',
    FOREIGN KEY (invoice_id) REFERENCES ap_invoices(id)
);

CREATE TABLE ap_payments (
    id INTEGER PRIMARY KEY,
    transaction_sequence_id BIGINT NOT NULL,
    invoice_id INTEGER NOT NULL,
    payment_date INTEGER NOT NULL,
    amount DECIMAL(14,4) NOT NULL,
    discount_amount DECIMAL(14,4) DEFAULT 0,
    net_amount DECIMAL(14,4) NOT NULL,
    payment_method VARCHAR DEFAULT 'EFT',
    status VARCHAR DEFAULT 'completed',
    FOREIGN KEY (invoice_id) REFERENCES ap_invoices(id)
);

CREATE TABLE ar_receipts (
    id INTEGER PRIMARY KEY,
    transaction_sequence_id BIGINT NOT NULL,
    invoice_id INTEGER NOT NULL,
    receipt_date INTEGER NOT NULL,
    amount DECIMAL(14,4) NOT NULL,
    status VARCHAR DEFAULT 'completed',
    FOREIGN KEY (invoice_id) REFERENCES ar_invoices(id)
);

